package com.companion.controller;
import com.companion.common.result.Result; import com.companion.dto.request.*; import com.companion.dto.response.CharacterImageGenerationResponse; import com.companion.security.AuthenticatedUser; import com.companion.service.CharacterImageGenerationService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequiredArgsConstructor @RequestMapping("/api/character-images") public class CharacterImageController {private final CharacterImageGenerationService service; @PostMapping("/generations") public Result<CharacterImageGenerationResponse> generate(@AuthenticationPrincipal AuthenticatedUser u,@Valid @RequestBody CharacterImageGenerateRequest r){return Result.success(service.generate(u.userId(),r));} @PostMapping("/confirm") public Result<Void> confirm(@AuthenticationPrincipal AuthenticatedUser u,@Valid @RequestBody CharacterImageConfirmRequest r){service.confirm(u.userId(),r);return Result.success();}}
